import{_ as e,o as a,c as s,a2 as i}from"./chunks/framework.BU31gs4v.js";const g=JSON.parse('{"title":"第 0 章 本书怎么读","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/00-how-to-read.md","filePath":"chapters/00-how-to-read.md","lastUpdated":1791479463000}'),o={name:"chapters/00-how-to-read.md"};function n(d,t,l,r,c,p){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="第-0-章-本书怎么读" tabindex="-1">第 0 章 本书怎么读 <a class="header-anchor" href="#第-0-章-本书怎么读" aria-label="Permalink to &quot;第 0 章 本书怎么读&quot;">​</a></h1><blockquote><p>本章目标：知道这本书要带你做成什么、怎么准备环境、怎么对照着源码读。前置：会写 TypeScript，会用 git。对应代码：<code>code/mini-letta</code>（tag <code>v0.1</code>～<code>v1.0</code>）。</p></blockquote><h2 id="_0-1-这本书要解决什么问题" tabindex="-1">0.1 这本书要解决什么问题 <a class="header-anchor" href="#_0-1-这本书要解决什么问题" aria-label="Permalink to &quot;0.1 这本书要解决什么问题&quot;">​</a></h2><p>几乎每个用过 coding agent 的人都遇到过同一件事：你在上午告诉它“我们用 pnpm，不要用 npm”，下午开一个新会话，它又敲出了 <code>npm install</code>。</p><p>模型本身不记事。它在每一次调用里看到的，只有这一次请求里塞进去的 token。所谓“记忆”，是 <strong>harness（模型外面那层程序）</strong> 替它保存、整理，并在下一次调用时重新塞回上下文里的东西。</p><p><a href="https://github.com/letta-ai/letta-code" target="_blank" rel="noreferrer">Letta Code</a> 是把这件事做得最彻底的开源 harness 之一。它的系统提示里有一句话概括了整个设计哲学：</p><blockquote><p>the model is the engine; <em>you</em> are the tokens.（模型只是引擎；<em>你</em>是那些 token。） —— <code>src/agent/prompts/letta_root_memfs.md:3</code></p></blockquote><p>这本书只讲 letta-code 的<strong>记忆子系统</strong>：</p><ul><li>记忆存在哪里？——一个 git 仓库，里面是 Markdown 文件（MemFS）；</li><li>记忆怎么进入模型？——每次对话开始时把<strong>已提交</strong>的记忆“编译”进系统提示；</li><li>上下文满了怎么办？——压缩（compaction），但原始消息永远可以被检索（recall）；</li><li>谁来整理记忆？——除了 agent 自己，还有对话结束后在后台运行的“反思”（reflection / sleeptime）子 agent；</li><li>多台机器、多个 agent 同时写怎么办？——git 同步、worktree 隔离、锁、内核级沙箱。</li></ul><p><strong>读完这本书，你能从零写出一个带长期记忆的 agent</strong>：它的记忆是 git 里的 Markdown，会被编译进系统提示，长对话会自动压缩并能找回被压掉的细节，空闲时会有后台子 agent 帮它整理记忆，记忆还能在机器之间同步。这个 agent 就是本书的配套项目 <strong>mini-letta</strong>。</p><h2 id="_0-2-配套项目-mini-letta" tabindex="-1">0.2 配套项目 mini-letta <a class="header-anchor" href="#_0-2-配套项目-mini-letta" aria-label="Permalink to &quot;0.2 配套项目 mini-letta&quot;">​</a></h2><p>mini-letta 用 <strong>Bun + TypeScript</strong> 写成（和 letta-code 同一套技术栈，只是降了一档：没有 Ink 终端 UI，用 readline；没有云端，用本地 bare 仓库扮演服务器）。它是一个独立的 git 仓库，每个 Part 结束打一个 tag，每个 tag 都能跑、测试都是绿的：</p><table tabindex="0"><thead><tr><th>版本</th><th>能力</th><th>对应章节</th></tr></thead><tbody><tr><td><code>v0.1</code></td><td>最小 agent loop、mock LLM、两个记忆块拼进系统提示</td><td>第 1–3 章，Lab 1</td></tr><tr><td><code>v0.2</code></td><td>MemFS：每个 agent 一个 git 记忆仓库、v2 布局、文件/bash 工具、pre-commit 校验</td><td>第 4–7 章，Lab 2</td></tr><tr><td><code>v0.3</code></td><td>系统提示编译器、按对话缓存、对话中途的 <code>&lt;memory_update&gt;</code>、回合后提醒</td><td>第 8–10 章，Lab 3</td></tr><tr><td><code>v0.4</code></td><td>token 预算、滑动窗口压缩、上下文 id 列表、BM25 recall 搜索</td><td>第 11–13 章，Lab 4</td></tr><tr><td><code>v0.5</code></td><td>后台反思：水位线、触发器、worktree 隔离、合并状态机、锁</td><td>第 14–17 章，Lab 5</td></tr><tr><td><code>v1.0</code></td><td>远端同步、跨 agent 隔离（路径守卫 + bwrap）、Memory Palace 网页、端到端脚本、Docker</td><td>第 18–20 章，Lab 6</td></tr></tbody></table><p>想看某一章到底加了什么代码，直接：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code/mini-letta</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stat</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/agent/system-prompt.ts</span></span></code></pre></div><h2 id="_0-3-准备环境" tabindex="-1">0.3 准备环境 <a class="header-anchor" href="#_0-3-准备环境" aria-label="Permalink to &quot;0.3 准备环境&quot;">​</a></h2><p>你需要：</p><ul><li><strong>Bun ≥ 1.3</strong>（本书用 1.3.11 验证）；</li><li><strong>git ≥ 2.24</strong>（本书用 2.43）；</li><li>可选：<strong>Ollama</strong>，用来跑一次真模型（本书用 <code>qwen2.5:3b</code>）；</li><li>可选：Linux 上的 <strong>bubblewrap</strong>（<code>bwrap</code>），第 19 章的内核沙箱要用；</li><li>可选：Docker，Lab 6 的部署要用。</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> code/mini-letta</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                         # 50 个测试，全部离线</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MINI_LETTA_HOME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mktemp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 永远在临时目录里玩，别污染真实状态</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/cli.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;记住：我用 pnpm&quot;</span></span></code></pre></div><p><code>MINI_LETTA_HOME</code> 对应 letta-code 的 <code>LETTA_LOCAL_BACKEND_DIR</code>。letta-code 的 CLAUDE.md 专门提醒过：手动试本地后端时“set <code>LETTA_LOCAL_BACKEND_DIR</code> to a temporary directory first. Otherwise the run reads and mutates your real <code>~/.letta/lc-local-backend</code>”。我们照做。</p><p><strong>为什么默认用 mock 模型？</strong> 记忆系统的大部分逻辑（git、编译、压缩、合并）和模型聪不聪明无关。一个确定性的 mock 模型让每一章的输出都可复现、每个测试都稳定。但我们也会在关键处换上真模型——而真模型（尤其是小模型）会以各种方式“不守规矩”：声称提交了其实没提交、只说“我现在去读文件”然后就结束了……这些都是本书里<strong>真实观察到的</strong>行为，它们直接推动了 mini-letta 里好几处防御设计。</p><h2 id="_0-4-怎么读-letta-code-源码" tabindex="-1">0.4 怎么读 letta-code 源码 <a class="header-anchor" href="#_0-4-怎么读-letta-code-源码" aria-label="Permalink to &quot;0.4 怎么读 letta-code 源码&quot;">​</a></h2><p>本书引用的源码都来自 <strong>letta-ai/letta-code @ <code>70ead335</code></strong>。引用格式是 <code>路径:行号</code>，例如 <code>src/backend/local/system-prompt-compilation.ts:432</code>。所有行号都在这个 commit 上用 <code>grep -n</code> 核对过。</p><p>letta-code 很大（<code>src/</code> 下几千个文件），读之前先建立三个认识：</p><p><strong>1. 分层。</strong> letta-code 的 CLAUDE.md 定义了严格的层次（<code>cli/ → websocket/ → agent/ → tools/ → backend/ → …→ utils/</code>），只允许向下依赖。记忆相关的代码主要在三处：</p><table tabindex="0"><thead><tr><th>目录</th><th>放了什么</th></tr></thead><tbody><tr><td><code>src/agent/memory-*.ts</code></td><td>MemFS 的 git 操作、格式规则、worktree、锁、冲突修复</td></tr><tr><td><code>src/backend/local/</code></td><td>本地后端：系统提示编译、压缩、transcript 搜索</td></tr><tr><td><code>src/cli/helpers/reflection-*.ts</code>、<code>memory-reminder.ts</code></td><td>反思的触发、transcript 切片、启动与收尾</td></tr></tbody></table><p><strong>2. 三条编排路径。</strong> 交互式 TUI（<code>src/cli/app/</code>）、headless（<code>src/headless.ts</code>）、websocket 监听器（<code>src/websocket/listener/</code>）各有一套回合编排代码。同一个“回合结束后同步记忆”的动作，在三处分别被调用（见第 3 章）。本书主要沿 headless 和本地后端读，因为它们最直接。</p><p><strong>3. 两种后端。</strong> Cloud（Letta 服务器保存 agent，记忆仓库托管在服务器上）和 Local（<code>LETTA_LOCAL_BACKEND_EXPERIMENTAL=1</code>，一切都在本机）。本书主要读 <strong>Local</strong> 后端：它把服务器端做的事（比如系统提示编译）也搬到了本地，读起来是一个完整闭环。</p><p>如果你想在本机跑 letta-code 的测试或小实验，建议像本书这样<strong>克隆一份到临时目录再 <code>bun install</code></strong>，不要在你正在开发的工作区里装依赖。另外注意：letta-code 的测试预加载脚本会把 <code>HOME</code> 换成临时目录（<code>scripts/test-home-preload.ts:48</code>），这意味着你的全局 git 配置在测试里<strong>不生效</strong>——第 16 章会讲到这件事怎么让我们误判过一次。</p><h2 id="_0-5-每章的结构" tabindex="-1">0.5 每章的结构 <a class="header-anchor" href="#_0-5-每章的结构" aria-label="Permalink to &quot;0.5 每章的结构&quot;">​</a></h2><p>每章大致是：</p><ol><li><strong>问题与概念</strong>——为什么需要它；</li><li><strong>letta-code 是怎么做的</strong>——按调用顺序读源码，带行号和不超过 20 行的摘录；</li><li><strong>自己实现一遍</strong>——mini-letta 的关键代码，以及“省略了什么、为什么”；</li><li><strong>运行与验证</strong>——精确的命令和<strong>真实</strong>输出；</li><li><strong>练习</strong>——一道巩固、一道扩展、一道读源码；</li><li><strong>延伸阅读</strong>。</li></ol><p>关于诚实：书里的“踩坑记录”只写真的踩到的坑；凡是输出，都是实际运行得到的；凡是对 letta-code 行为的断言，要么有源码行号，要么有我们跑过的探针实验，要么明确标注“未验证”。</p><h2 id="_0-6-阅读路线" tabindex="-1">0.6 阅读路线 <a class="header-anchor" href="#_0-6-阅读路线" aria-label="Permalink to &quot;0.6 阅读路线&quot;">​</a></h2><ul><li><strong>只想理解思想</strong>：第 1、3、9、15、16 章。</li><li><strong>想自己实现一个</strong>：按顺序读，每个 Lab 都动手。</li><li><strong>在给 letta-code 贡献代码</strong>：重点看第 9 章（<code>&lt;memory_update&gt;</code> 的生命周期）和第 16 章（全局 <code>core.autocrlf</code> 与反思 worktree），这两处我们用探针在 <code>70ead335</code> 上观察到了值得注意的行为；第 15 章的“空反思被当成成功”是在 mini-letta 里用真模型踩到的，letta-code 是否有同样的问题我们<strong>没有验证</strong>，章里给出了该去看的代码位置。</li></ul><p>下一章，我们从最根本的问题开始：agent 为什么需要记忆，以及“记忆”到底分几种。</p>`,36)])])}const k=e(o,[["render",n]]);export{g as __pageData,k as default};
